<script setup>
import axios from 'axios';
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import MoneyInput from '../../components/MoneyInput.vue';
import PaginationControls from '../../components/PaginationControls.vue';
import RecordDetailHero from '../../components/RecordDetailHero.vue';
import { useConfirmDialog } from '../../composables/useConfirmDialog';
import { useUnsavedForm } from '../../composables/useUnsavedForm';

import { formatRupiah } from '../../utils/money';
import { formatDateOnly } from '../../utils/dateOnly';
const props = defineProps({ workspaceId: { type: [String, Number], required: true }, mode: { type: String, required: true } });
const route = useRoute();
const router = useRouter();
const { open: confirmOpen, options: confirmOptions, confirm: askConfirm, finish: finishConfirm } = useConfirmDialog();
const titles = { accounts: ['Akun','Kelola sumber saldo kas dan rekening.'], transactions: ['Transaksi','Catat mutasi aktual dan transfer tanpa menghitung saldo ganda.'], budgets: ['Anggaran','Bandingkan rencana alokasi dengan realisasi biaya.'], savings: ['Tabungan','Buat target bersama dan catat setiap setoran.'] };
const rows = ref([]); const accounts = ref([]); const events = ref([]); const obligations = ref([]); const paymentPagination = ref(null); const paymentPage = ref(1); const deposits = ref([]); const depositPagination = ref(null); const selected = ref(null); const loading = ref(true); const saving = ref(false); const error = ref(''); const formError = ref(''); const dialog = ref(''); const budgetTab = ref(route.query.tab === 'payments' ? 'payments' : 'categories'); const filters = reactive({ type: '', category: String(route.query.category||''), account_id: String(route.query.account_id||''), month: new Date().toLocaleDateString('en-CA').slice(0,7) });
const transactionDetail = ref(null); const accountDetail = ref(null); const accountTransactions = ref([]);
const selectedDeposit = ref(null);
const budgetDetail = ref(null); const budgetTransactions = ref([]); const budgetObligations = ref([]); const budgetNeeds = ref([]);
const accountForm = reactive(blankAccount()); const transactionForm = reactive(blankTransaction()); const budgetForm = reactive(blankBudget()); const obligationForm = reactive(blankObligation()); const goalForm = reactive(blankGoal()); const depositForm = reactive(blankDeposit()); const paymentForm = reactive({ account_id:'', amount:'', paid_at:new Date().toLocaleDateString('en-CA'), notes:'' });
const dialogForms = { account: accountForm, transaction: transactionForm, category: budgetForm, obligation: obligationForm, goal: goalForm, deposit: depositForm, payment: paymentForm };
const dialogSnapshot = ref('');
const dialogDirty = computed(() => Boolean(dialog.value) && JSON.stringify(dialogForms[dialog.value]) !== dialogSnapshot.value);
const dialogGuard = useUnsavedForm({ isOpen: computed(() => Boolean(dialog.value)), isDirty: dialogDirty, confirm: askConfirm, onDiscard: () => { dialog.value = ''; selectedDeposit.value = null; } });
const heading = computed(() => props.mode==='savings'&&selected.value?selected.value.name:props.mode==='budgets'&&budgetDetail.value?budgetDetail.value.name:(titles[props.mode]?.[0]??'Keuangan'));
const description = computed(() => props.mode==='savings'&&selected.value?'Pantau progres, histori, dan setoran tujuan ini.':props.mode==='budgets'&&budgetDetail.value?`${budgetDetail.value.event?.title||'Semua acara'} · Rencana dibandingkan dengan transaksi pengeluaran aktual.`:(titles[props.mode]?.[1]??''));
function dateLabel(value) { return formatDateOnly(value); }
function blankAccount(){ return {name:'',account_type:'cash',institution:'',opening_balance:0}; }
function blankTransaction(){ return {type:'expense',account_id:'',destination_account_id:'',category:'',description:'',amount:'',occurred_at:new Date().toLocaleDateString('en-CA'),notes:''}; }
function blankBudget(){ return {name:'',planned_amount:'',event_id:'',color:'',notes:''}; }
function blankObligation(){ return {title:'',vendor_name:'',budget_category_id:'',event_id:'',total_amount:'',due_at:'',notes:''}; }
function blankGoal(){ return {name:'',target_amount:'',target_date:'',notes:''}; }
function blankDeposit(){ return {amount:'',deposited_at:new Date().toLocaleDateString('en-CA'),account_id:'',notes:''}; }
function categoryLabel(item){ return item.category || '—'; }
function progress(item){ return item.target_amount ? Math.min(100,Math.round(Number(item.saved_amount||0)/Number(item.target_amount)*100)) : 0; }
function selectBudgetTab(tab){ budgetTab.value=tab; router.replace({query:{...route.query,tab:tab==='categories'?undefined:tab}}); }
function showDialog(name) { dialog.value = name; dialogSnapshot.value = JSON.stringify(dialogForms[name]); }

async function load(){
    loading.value=true; error.value='';
    try {
        if(props.mode==='accounts') { const {data}=await axios.get(`/api/workspaces/${props.workspaceId}/accounts`); rows.value=data.accounts; const accountId=route.path.split('/')[3]; const account=rows.value.find(item=>String(item.id)===accountId); if(account) await openAccount(account); else accountDetail.value=null; }
        if(props.mode==='transactions') { const {data}=await axios.get(`/api/workspaces/${props.workspaceId}/transactions`,{params:Object.fromEntries(Object.entries(filters).filter(([,v])=>v))}); rows.value=data.transactions.data; accounts.value=(await axios.get(`/api/workspaces/${props.workspaceId}/accounts`)).data.accounts.filter(a=>!a.is_archived); }
        if(props.mode==='budgets') { const [b,p,a,e]=await Promise.all([axios.get(`/api/workspaces/${props.workspaceId}/budgets`),axios.get(`/api/workspaces/${props.workspaceId}/payment-obligations`,{params:{page:paymentPage.value,per_page:25}}),axios.get(`/api/workspaces/${props.workspaceId}/accounts`),axios.get(`/api/workspaces/${props.workspaceId}/events`,{params:{for_select:true}})]); rows.value=b.data.categories; obligations.value=p.data.obligations; paymentPagination.value=p.data.pagination; paymentPage.value=p.data.pagination.current_page; accounts.value=a.data.accounts.filter(x=>!x.is_archived); events.value=e.data.events; const categoryId=route.path.split('/')[3]; if(categoryId){const detail=await axios.get(`/api/budget-categories/${categoryId}`);budgetDetail.value=detail.data.category;budgetTransactions.value=detail.data.transactions;budgetObligations.value=detail.data.obligations;budgetNeeds.value=detail.data.needs||[];}else{budgetDetail.value=null;budgetTransactions.value=[];budgetObligations.value=[];budgetNeeds.value=[];} }
        if(props.mode==='savings') { const [g,a]=await Promise.all([axios.get(`/api/workspaces/${props.workspaceId}/savings`),axios.get(`/api/workspaces/${props.workspaceId}/accounts`)]); rows.value=g.data.goals; accounts.value=a.data.accounts.filter(x=>!x.is_archived); const goalId=route.path.split('/')[3]; if(goalId) await openGoal(goalId); else selected.value=null; }
    } catch { error.value=`${heading.value} belum berhasil dimuat. Coba lagi.`; } finally { loading.value=false; }
}
function openNew(){ formError.value=''; selected.value=null; if(props.mode==='accounts'){Object.assign(accountForm,blankAccount());showDialog('account');} if(props.mode==='transactions'){Object.assign(transactionForm,blankTransaction());transactionForm.account_id=String(accounts.value[0]?.id||'');showDialog('transaction');} if(props.mode==='budgets'){if(budgetTab.value==='categories'){Object.assign(budgetForm,blankBudget());showDialog('category');}else{Object.assign(obligationForm,blankObligation());showDialog('obligation');}} if(props.mode==='savings'){Object.assign(goalForm,blankGoal());showDialog('goal');} }
function editAccount(a){selected.value=a;Object.assign(accountForm,{name:a.name,account_type:a.account_type,institution:a.institution||'',opening_balance:a.opening_balance});showDialog('account');}
function editTransaction(t){selected.value=t;Object.assign(transactionForm,{type:t.type,account_id:String(t.account_id),destination_account_id:String(t.destination_account_id||''),category:t.category||'',description:t.description,amount:t.amount,occurred_at:String(t.occurred_at).slice(0,10),notes:t.notes||''});showDialog('transaction');}
function openTransaction(t){transactionDetail.value=t;}
async function openAccount(account){accountDetail.value=account;try{const {data}=await axios.get(`/api/workspaces/${props.workspaceId}/transactions`,{params:{account_id:account.id,per_page:20}});accountTransactions.value=data.transactions.data;}catch{accountTransactions.value=[];error.value='Mutasi akun belum berhasil dimuat.';}}
function editCategory(c){selected.value=c;Object.assign(budgetForm,{name:c.name,planned_amount:c.planned_amount,event_id:c.event_id?String(c.event_id):'',color:c.color||'',notes:c.notes||''});showDialog('category');}
function editObligation(o){selected.value=o;Object.assign(obligationForm,{title:o.title,vendor_name:o.vendor_name||'',budget_category_id:o.budget_category_id?String(o.budget_category_id):'',event_id:o.event_id?String(o.event_id):'',total_amount:o.total_amount,due_at:o.due_at||'',notes:o.notes||''});showDialog('obligation');}
function editGoal(g){selected.value=g;Object.assign(goalForm,{name:g.name,target_amount:g.target_amount,target_date:g.target_date||'',notes:g.notes||''});showDialog('goal');}
async function openGoal(id,page=1){try{const {data}=await axios.get(`/api/savings-goals/${id}`,{params:{page,per_page:25}});if(page>data.deposit_pagination.last_page&&data.deposit_pagination.last_page>0)return await openGoal(id,data.deposit_pagination.last_page);selected.value=data.goal;deposits.value=selected.value.deposits||[];depositPagination.value=data.deposit_pagination;}catch{error.value='Detail target tabungan belum berhasil dimuat.';}}
function changeDepositPage(page){if(selected.value)openGoal(selected.value.id,page);}
function openDeposit(deposit=null){selectedDeposit.value=deposit;Object.assign(depositForm,deposit?{amount:deposit.amount,deposited_at:String(deposit.deposited_at).slice(0,10),account_id:String(deposit.transaction?.account_id||''),notes:deposit.notes||''}:blankDeposit());if(!deposit)depositForm.account_id=String(accounts.value[0]?.id||'');showDialog('deposit');}
function changePaymentPage(page){paymentPage.value=page;load();}
function openPayment(o){selected.value=o;Object.assign(paymentForm,{account_id:String(accounts.value[0]?.id||''),amount:o.remaining_amount||'',paid_at:new Date().toLocaleDateString('en-CA'),notes:''});showDialog('payment');}
function openBudget(c){router.push('/app/budgets/'+c.id);}

async function save(){if(saving.value||!dialog.value)return;saving.value=true;formError.value='';try{
    if(dialog.value==='account'){if(selected.value) await axios.patch(`/api/accounts/${selected.value.id}`,accountForm);else await axios.post(`/api/workspaces/${props.workspaceId}/accounts`,accountForm);}
    if(dialog.value==='transaction'){const body={...transactionForm,account_id:Number(transactionForm.account_id),destination_account_id:transactionForm.destination_account_id?Number(transactionForm.destination_account_id):null};if(selected.value) await axios.patch(`/api/transactions/${selected.value.id}`,body);else await axios.post(`/api/workspaces/${props.workspaceId}/transactions`,body);}
    if(dialog.value==='category'){const body={...budgetForm,event_id:budgetForm.event_id?Number(budgetForm.event_id):null};if(selected.value) await axios.patch(`/api/budget-categories/${selected.value.id}`,body);else await axios.post(`/api/workspaces/${props.workspaceId}/budgets`,body);}
    if(dialog.value==='obligation'){const body={...obligationForm,budget_category_id:obligationForm.budget_category_id?Number(obligationForm.budget_category_id):null,event_id:obligationForm.event_id?Number(obligationForm.event_id):null};if(selected.value) await axios.patch(`/api/payment-obligations/${selected.value.id}`,body);else await axios.post(`/api/workspaces/${props.workspaceId}/payment-obligations`,body);}
    if(dialog.value==='goal'){const body={...goalForm,target_date:goalForm.target_date||null};if(selected.value) await axios.patch(`/api/savings-goals/${selected.value.id}`,body);else await axios.post(`/api/workspaces/${props.workspaceId}/savings`,body);}
    if(dialog.value==='deposit'){const body={...depositForm,account_id:depositForm.account_id?Number(depositForm.account_id):null};if(selectedDeposit.value)await axios.patch(`/api/savings-goals/${selected.value.id}/deposits/${selectedDeposit.value.id}`,body);else await axios.post(`/api/savings-goals/${selected.value.id}/deposits`,body);selectedDeposit.value=null;}
    if(dialog.value==='payment') await axios.post(`/api/payment-obligations/${selected.value.id}/payments`,{...paymentForm,account_id:Number(paymentForm.account_id)});
    const savedDialog=dialog.value;dialog.value='';if(savedDialog==='obligation')paymentPage.value=1;await load();if(props.mode==='savings'&&selected.value) await openGoal(selected.value.id);
}catch(e){formError.value=e.response?.data?.message??Object.values(e.response?.data?.errors??{}).flat()[0]??'Perubahan belum berhasil disimpan.';}finally{saving.value=false;}}

async function archiveAccount(a){if(!await askConfirm({title:`${a.is_archived?'Pulihkan':'Arsipkan'} akun “${a.name}”?`,message:a.is_archived?'Akun kembali tersedia untuk transaksi baru.':'Akun tidak dapat dipilih untuk transaksi baru. Histori dan saldo tetap tersimpan.',confirmLabel:a.is_archived?'Pulihkan akun':'Arsipkan akun',destructive:!a.is_archived}))return;try{await axios.patch(`/api/accounts/${a.id}`,{is_archived:!a.is_archived});await load();}catch(e){error.value=e.response?.data?.message??'Status akun belum berhasil diubah.';}}
async function voidTransaction(t){if(!await askConfirm({title:`Batalkan mutasi “${t.description}”?`,message:'Mutasi dibatalkan dan saldo akun akan dihitung ulang.',confirmLabel:'Batalkan mutasi'}))return;try{await axios.post(`/api/transactions/${t.id}/void`);transactionDetail.value=null;await load();}catch(e){error.value=e.response?.data?.message??'Mutasi tidak dapat dibatalkan.';}}
async function deleteCategory(c){if(!await askConfirm({title:`Hapus kategori “${c.name}”?`,message:'Histori transaksi yang memakai nama kategori ini tetap tersimpan.',confirmLabel:'Hapus kategori'}))return;try{await axios.delete(`/api/budget-categories/${c.id}`);if(String(route.path.split('/')[3])===String(c.id))await router.push('/app/budgets');await load();}catch(e){error.value=e.response?.data?.message??'Kategori belum berhasil dihapus.';}}
async function reverseDeposit(d){if(!await askConfirm({title:'Batalkan setoran ini?',message:'Setoran dihapus dari histori. Jika memakai akun sumber, saldo akun tersebut juga akan dikoreksi.',confirmLabel:'Batalkan setoran'}))return;try{await axios.delete(`/api/savings-goals/${selected.value.id}/deposits/${d.id}`);await openGoal(selected.value.id);await load();}catch(e){error.value=e.response?.data?.message??'Setoran belum berhasil dibatalkan.';}}
async function archiveGoal(g){if(!await askConfirm({title:`${g.is_archived?'Pulihkan':'Arsipkan'} target “${g.name}”?`,message:g.is_archived?'Target dapat dipakai kembali.':'Target disembunyikan dari daftar aktif, tetapi histori setoran tetap tersimpan.',confirmLabel:g.is_archived?'Pulihkan target':'Arsipkan target',destructive:!g.is_archived}))return;try{await axios.patch(`/api/savings-goals/${g.id}`,{is_archived:!g.is_archived});await router.push('/app/savings');await load();}catch(e){error.value=e.response?.data?.message??'Target belum berhasil diperbarui.';}}
onMounted(load);
watch(() => route.path, (path) => {
    const id = path.split('/')[3];
    if (props.mode === 'savings') {
        if (id) openGoal(id);
        else { selected.value = null; deposits.value = []; depositPagination.value = null; }
    }
    if (props.mode === 'accounts') {
        const account = rows.value.find(item => String(item.id) === id);
        if (account) openAccount(account);
        else accountDetail.value = null;
    }
    if (props.mode === 'budgets') load();
});
watch(() => route.query.tab, (tab) => { if (props.mode === 'budgets') budgetTab.value = tab === 'payments' ? 'payments' : 'categories'; });
</script>

<template>
    <section class="financial-records" :class="`financial-records--${mode}`" :aria-label="heading">
        <header v-if="!(mode==='savings'&&selected) && !(mode==='budgets'&&budgetDetail) && !(mode==='accounts'&&accountDetail)" class="records-head"><div><p class="eyebrow"><span class="eyebrow__dot"></span> RENCANA DANA KALIAN</p><h1 :id="`finance-${mode}-title`">{{ heading }}</h1><p>{{ description }}</p></div><button class="button button--primary" @click="openNew"><FaIcon :icon="['fas','plus']" /> {{ {accounts:'Tambah akun',transactions:'Catat transaksi',budgets:budgetTab==='categories'?'Tambah kategori':'Tambah kewajiban',savings:'Buat target'}[mode] }}</button></header>
        <div v-if="loading" class="home-skeleton"><div class="skeleton-line skeleton-line--title"></div><div class="skeleton-block"></div></div><div v-else-if="error" class="page-error" role="alert"><p>{{ error }}</p><button class="button button--quiet" @click="load">Coba lagi</button></div>
        <template v-else>
            <template v-if="mode==='accounts'"><section v-if="accountDetail" class="account-detail-page"><RecordDetailHero id="account-detail-title" heading-tag="h1" eyebrow="DETAIL AKUN" :title="accountDetail.name" :subtitle="accountDetail.institution||({bank:'Rekening bank',cash:'Kas tunai',other:'Akun lainnya'}[accountDetail.account_type]||'Sumber dana bersama')"><template #meta><span class="record-detail-chip">{{ accountDetail.account_type==='bank'?'Rekening bank':accountDetail.account_type==='cash'?'Kas tunai':'Akun lainnya' }}</span><span class="record-detail-chip" :class="accountDetail.is_archived?'record-detail-chip--muted':''">{{ accountDetail.is_archived?'Diarsipkan':'Aktif' }}</span></template><template #actions><button class="button button--quiet" @click="router.push('/app/accounts')"><FaIcon :icon="['fas','chevron-left']" /> Semua akun</button><button class="button button--quiet" @click="archiveAccount(accountDetail)">{{ accountDetail.is_archived?'Pulihkan akun':'Arsipkan akun' }}</button><button class="button button--primary" @click="editAccount(accountDetail)">Ubah akun</button></template></RecordDetailHero><div class="account-detail-balance"><span>SALDO SAAT INI</span><strong>{{ formatRupiah(accountDetail.balance) }}</strong><small>Saldo awal dan mutasi aktif</small></div><dl class="finance-detail"><div><dt>Jenis akun</dt><dd>{{ accountDetail.account_type==='bank'?'Rekening bank':accountDetail.account_type==='cash'?'Kas tunai':'Akun lainnya' }}</dd></div><div><dt>Bank / institusi</dt><dd>{{ accountDetail.institution||'Tidak dicatat' }}</dd></div><div><dt>Status</dt><dd>{{ accountDetail.is_archived?'Diarsipkan':'Aktif' }}</dd></div></dl><section><div class="deposit-history__head"><div><p class="eyebrow">RIWAYAT AKUN</p><h2>Mutasi terbaru</h2></div><RouterLink class="text-link" :to="{path:'/app/transactions',query:{account_id:accountDetail.id}}">Semua transaksi</RouterLink></div><div v-if="!accountTransactions.length" class="records-hint">Belum ada mutasi pada akun ini.</div><button v-for="t in accountTransactions" :key="t.id" class="account-transaction" @click="router.push('/app/transactions?account_id='+accountDetail.id)"><span>{{ t.description }}<small>{{ dateLabel(t.occurred_at) }}</small></span><strong>{{ formatRupiah(t.amount) }}</strong></button></section></section><div v-else class="records-hint">Saldo dihitung dari saldo awal dan transaksi aktif. Transfer hanya menggeser dana di antara akun kalian.</div><div v-if="!accountDetail" class="account-grid"><article v-for="account in rows" :key="account.id" class="account-card" :class="{'account-card--archived':account.is_archived}"><button class="account-card__overview" @click="router.push('/app/accounts/'+account.id)"><div class="account-card__top"><span class="account-icon"><FaIcon :icon="['fas',account.account_type==='bank'?'building-columns':'wallet']" /></span><span>{{ account.is_archived?'Diarsipkan':account.account_type==='bank'?'Bank':account.account_type==='cash'?'Tunai':'Lainnya' }}</span></div><h2>{{ account.name }}</h2><p>{{ account.institution||'Sumber dana bersama' }}</p><strong>{{ formatRupiah(account.balance) }}</strong><small>Lihat mutasi <FaIcon :icon="['fas','arrow-right']" /></small></button><footer><button class="button button--quiet" @click="editAccount(account)">Ubah</button><button class="button button--quiet" @click="archiveAccount(account)">{{ account.is_archived?'Pulihkan':'Arsipkan' }}</button></footer></article><div v-if="!rows.length" class="records-empty"><h2>Belum ada akun kas atau bank.</h2><p>Tambahkan saldo awal untuk menghitung mutasi berikutnya.</p><button class="button button--primary" @click="openNew">Tambah akun pertama</button></div></div></template>

            <template v-else-if="mode==='transactions'"><section class="records-toolbar"><MotionSelect v-model="filters.type" aria-label="Jenis transaksi" @change="load"><option value="">Semua jenis</option><option value="income">Pemasukan</option><option value="expense">Pengeluaran</option><option value="transfer">Transfer</option></MotionSelect><MotionSelect v-model="filters.account_id" aria-label="Akun" @change="load"><option value="">Semua akun</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.name }}</option></MotionSelect><input v-model="filters.month" type="month" aria-label="Bulan transaksi" @change="load" /><span v-if="filters.category" class="records-filter-chip">Kategori: {{ filters.category }}<button type="button" aria-label="Hapus filter kategori" @click="filters.category='';load()">Hapus</button></span></section><div class="transaction-list"><article v-for="t in rows" :key="t.id" class="transaction-row" @click="openTransaction(t)"><span class="transaction-mark" :class="`transaction-mark--${t.type}`"><FaIcon :icon="['fas',t.type==='income'?'arrow-down':t.type==='transfer'?'rotate':'arrow-up']" /></span><span class="transaction-copy"><strong>{{ t.description }}</strong><small>{{ t.category||'Transfer akun' }} · {{ t.account?.name }}<template v-if="t.destination_account"> → {{ t.destination_account.name }}</template> · {{ dateLabel(t.occurred_at) }}</small></span><strong class="transaction-amount" :class="{'transaction-amount--in':t.type==='income'}">{{ t.type==='income'?'+':t.type==='expense'?'−':'' }}{{ formatRupiah(t.amount) }}</strong><FaIcon class="transaction-chevron" :icon="['fas','chevron-right']" /></article><div v-if="!rows.length" class="records-empty"><h2>Belum ada mutasi pada periode ini.</h2><p>Catat transaksi aktual atau pindahkan saldo antar akun.</p><button class="button button--primary" @click="openNew">Catat transaksi</button></div></div></template>

            <template v-else-if="mode==='budgets'"><nav class="records-tabs"><button :class="{'is-active':budgetTab==='categories'}" :aria-current="budgetTab==='categories'?'page':undefined" @click="selectBudgetTab('categories')">Alokasi anggaran</button><button :class="{'is-active':budgetTab==='payments'}" :aria-current="budgetTab==='payments'?'page':undefined" @click="selectBudgetTab('payments')">Kewajiban & pembayaran</button></nav><template v-if="budgetTab==='categories'"><section v-if="budgetDetail" class="budget-detail-page"><RecordDetailHero id="budget-detail-title" heading-tag="h1" eyebrow="DETAIL ANGGARAN" :title="budgetDetail.name" :subtitle="budgetDetail.event?.title||'Semua acara'"><template #meta><span class="record-detail-chip">{{ budgetDetail.event?.title||'Berlaku untuk semua acara' }}</span></template><template #actions><button class="button button--quiet" @click="router.push('/app/budgets')"><FaIcon :icon="['fas','chevron-left']" /> Semua kategori</button><button class="button button--quiet" @click="deleteCategory(budgetDetail)">Hapus kategori</button><button class="button button--primary" @click="editCategory(budgetDetail)">Ubah kategori</button></template></RecordDetailHero><section class="budget-detail-summary"><div><span>RENCANA</span><strong>{{ formatRupiah(budgetDetail.planned_amount) }}</strong></div><div><span>REALISASI</span><strong>{{ formatRupiah(budgetDetail.actual_amount) }}</strong></div><div><span>SISA ANGGARAN</span><strong :class="{'over-budget':budgetDetail.remaining_amount<0}">{{ formatRupiah(Math.abs(budgetDetail.remaining_amount)) }}</strong></div><div class="progress-track"><span :style="{width:`${budgetDetail.planned_amount?Math.min(100,budgetDetail.actual_amount/budgetDetail.planned_amount*100):0}%`}"></span></div><p>{{ budgetDetail.remaining_amount<0?'Pengeluaran melampaui rencana.':'Pengeluaran aktual dibandingkan dengan rencana kategori.' }}</p></section><section class="budget-detail-list"><div><div><p class="eyebrow">TERMIN TERKAIT</p><h2>Kewajiban pembayaran</h2></div><button class="button button--quiet" @click="selectBudgetTab('payments')">Lihat semua pembayaran</button></div><article v-for="item in budgetObligations" :key="item.id"><span><strong>{{ item.title }}</strong><small>{{ item.vendor_name||'Vendor belum dipilih' }} · {{ dateLabel(item.due_at) }}</small></span><strong>{{ formatRupiah(item.total_amount) }}</strong></article><p v-if="!budgetObligations.length" class="records-hint">Belum ada kewajiban yang terhubung ke kategori ini.</p></section><section class="budget-detail-list"><div><div><p class="eyebrow">PENGELUARAN AKTUAL</p><h2>Transaksi kategori</h2></div><RouterLink class="text-link" :to="{path:'/app/transactions',query:{category:budgetDetail.name}}">Buka transaksi</RouterLink></div><article v-for="item in budgetTransactions" :key="item.id"><span><strong>{{ item.description }}</strong><small>{{ item.account?.name||'Akun tidak tersedia' }} · {{ dateLabel(item.occurred_at) }}</small></span><strong>{{ formatRupiah(item.amount) }}</strong></article><p v-if="!budgetTransactions.length" class="records-hint">Belum ada pengeluaran dengan kategori ini.</p></section><section class="budget-detail-list"><div><div><p class="eyebrow">KEBUTUHAN TERKAIT</p><h2>Barang dan jasa</h2></div><RouterLink class="text-link" :to="{path:'/app/needs',query:{budget_category_id:String(budgetDetail.id)}}">Buka kebutuhan</RouterLink></div><article v-for="need in budgetNeeds" :key="need.id"><span><RouterLink :to="`/app/needs/${need.id}`"><strong>{{ need.title }}</strong></RouterLink><small>{{ need.quantity }} unit · {{ need.status==='purchased'?'Sudah dibeli':'Belum dibeli' }}</small></span><strong>{{ formatRupiah(need.status==='purchased'?need.purchased_amount:need.estimated_amount) }}</strong></article><p v-if="!budgetNeeds.length" class="records-hint">Belum ada kebutuhan yang ditautkan ke kategori ini.</p></section></section><div v-else class="budget-grid"><article v-for="c in rows" :key="c.id" class="budget-card"><div><span class="budget-color" :style="{background:c.color||'#809176'}"></span><div><button class="budget-title" @click="openBudget(c)">{{ c.name }}</button><small>{{ c.event?.title||'Semua acara' }}</small></div><button class="icon-button" :aria-label="`Ubah ${c.name}`" @click="editCategory(c)"><FaIcon :icon="['fas','ellipsis']" /></button></div><strong class="budget-card__plan">{{ formatRupiah(c.planned_amount) }}</strong><div class="budget-card__actual"><span>Realisasi</span><b>{{ formatRupiah(c.actual_amount) }}</b></div><div class="progress-track"><span :style="{width:`${c.planned_amount?Math.min(100,c.actual_amount/c.planned_amount*100):0}%`}"></span></div><p :class="{'over-budget':c.remaining_amount<0}">{{ c.remaining_amount<0?'Melebihi rencana ':'Sisa anggaran ' }}{{ formatRupiah(Math.abs(c.remaining_amount)) }}</p><footer><button class="button button--quiet" @click="openBudget(c)">Detail</button><button class="button button--quiet" @click="editCategory(c)">Ubah kategori</button><button class="button button--quiet" @click="deleteCategory(c)">Hapus</button></footer></article><div v-if="!rows.length" class="records-empty"><h2>Belum ada alokasi biaya.</h2><p>Anggaran adalah rencana. Pengeluaran aktual dicatat di Transaksi.</p><button class="button button--primary" @click="openNew">Tambah kategori</button></div></div></template><template v-else><div class="obligation-list"><article v-for="o in obligations" :key="o.id" class="obligation-row"><span class="obligation-date">{{ dateLabel(o.due_at) }}</span><span class="transaction-copy"><strong>{{ o.title }}</strong><small>{{ o.vendor_name||'Vendor belum dipilih' }} · {{ o.budget_category?.name||'Tanpa kategori anggaran' }}</small></span><span><strong>{{ formatRupiah(o.paid_amount) }}</strong><small> dari {{ formatRupiah(o.total_amount) }}</small></span><span class="obligation-status">{{ Number(o.remaining_amount)===0?'Lunas':formatRupiah(o.remaining_amount)+' tersisa' }}</span><button v-if="Number(o.remaining_amount)>0" class="button button--primary" @click="openPayment(o)">Catat bayar</button><button v-else class="button button--quiet" @click="editObligation(o)">Detail</button></article><div v-if="!obligations.length" class="records-empty"><h2>Belum ada kewajiban pembayaran.</h2><p>Catat termin/vendor yang perlu dibayar, lalu tautkan pembayarannya ke transaksi aktual.</p><button class="button button--primary" @click="openNew">Tambah kewajiban</button></div></div><PaginationControls v-if="paymentPagination" :pagination="paymentPagination" @change="changePaymentPage" /></template></template>

            <template v-else-if="mode==='savings' && selected"><RecordDetailHero id="savings-goal-detail-title" heading-tag="h1" eyebrow="DETAIL TABUNGAN" :title="selected.name" :subtitle="selected.target_date?`Target ${dateLabel(selected.target_date)}`:'Target dana bersama'"><template #meta><span class="record-detail-chip">{{ selected.is_archived?'Diarsipkan':'Sedang dikumpulkan' }}</span><span class="record-detail-chip record-detail-chip--muted">{{ progress(selected) }}% tercapai</span></template><template #actions><button class="button button--quiet" @click="router.push('/app/savings')"><FaIcon :icon="['fas','chevron-left']" /> Semua target</button><button class="button button--quiet" @click="archiveGoal(selected)">{{ selected.is_archived?'Pulihkan':'Arsipkan' }}</button><button class="button button--primary" @click="editGoal(selected)">Ubah target</button></template></RecordDetailHero><div class="goal-detail"><div class="goal-progress-card"><span>PROGRES TARGET</span><strong>{{ formatRupiah(selected.saved_amount) }} <small>dari {{ formatRupiah(selected.target_amount) }}</small></strong><div class="progress-track"><span :style="{width:`${progress(selected)}%`}"></span></div><p>{{ progress(selected) }}% · Sisa {{ formatRupiah(Math.max(Number(selected.target_amount)-Number(selected.saved_amount||0),0)) }}</p><footer><button class="button button--primary" @click="openDeposit()">Catat setoran</button></footer></div><section class="deposit-history"><div class="deposit-history__head"><div><p class="eyebrow">RIWAYAT DANA</p><h2>Setoran</h2></div><span>{{ depositPagination?.total ?? deposits.length }} catatan</span></div><article v-for="d in deposits" :key="d.id"><div><strong>{{ dateLabel(d.deposited_at) }}</strong><small>{{ d.transaction?.account?.name||'Catatan setoran' }} · {{ d.notes||'Setoran target' }}</small></div><strong>{{ formatRupiah(d.amount) }}</strong><span class="deposit-actions"><button class="text-action" @click="openDeposit(d)">Ubah</button><button class="icon-button" :aria-label="`Batalkan setoran tanggal ${dateLabel(d.deposited_at)}`" @click="reverseDeposit(d)"><FaIcon :icon="['fas','rotate']" /></button></span></article><p v-if="!depositPagination?.total" class="records-hint">Belum ada setoran. Setoran tanpa akun sumber tidak mengubah saldo kas/bank.</p><PaginationControls v-if="depositPagination" :pagination="depositPagination" @change="changeDepositPage" /></section></div></template>
            <template v-else-if="mode==='savings'"><div class="goal-grid"><article v-for="g in rows" :key="g.id" class="goal-card" :class="{'goal-card--archived':g.is_archived}" @click="router.push('/app/savings/'+g.id)"><div class="goal-card__top"><span :class="{'goal-card__icon--archived':g.is_archived}"><FaIcon :icon="['fas',g.is_archived?'box-archive':'heart']" /></span><small v-if="g.is_archived" class="goal-card__archive-badge"><FaIcon :icon="['fas','box-archive']" /> Diarsipkan</small><small v-else>{{ dateLabel(g.target_date) }}</small></div><h2>{{ g.name }}</h2><strong>{{ formatRupiah(g.saved_amount) }}</strong><small>dari {{ formatRupiah(g.target_amount) }}</small><div class="progress-track"><span :style="{width:`${progress(g)}%`}"></span></div><footer><span>{{ progress(g) }}% terkumpul</span><button :class="['button',g.is_archived?'button--primary':'button--quiet']" @click.stop="g.is_archived?archiveGoal(g):editGoal(g)"><FaIcon v-if="g.is_archived" :icon="['fas','rotate']" />{{ g.is_archived?'Pulihkan':'Ubah target' }}</button></footer></article><div v-if="!rows.length" class="records-empty"><h2>Belum ada tujuan tabungan.</h2><p>Mulai dari target sederhana, lalu catat dana yang benar-benar disetorkan.</p><button class="button button--primary" @click="openNew">Buat target pertama</button></div></div></template>
        </template>

        <Transition name="overlay" appear>
        <div v-if="transactionDetail" class="sheet-backdrop" @click.self="transactionDetail=null"><aside class="guest-sheet finance-sheet" role="dialog" aria-modal="true" aria-labelledby="transaction-detail-title"><RecordDetailHero id="transaction-detail-title" heading-tag="h2" eyebrow="DETAIL MUTASI" :title="transactionDetail.description" :subtitle="dateLabel(transactionDetail.occurred_at)"><template #meta><span class="record-detail-chip" :class="transactionDetail.type==='expense'?'record-detail-chip--warning':''">{{ {income:'Pemasukan',expense:'Pengeluaran',transfer:'Transfer'}[transactionDetail.type] }}</span><span class="record-detail-chip record-detail-chip--muted">{{ formatRupiah(transactionDetail.amount) }}</span></template><template #actions><button class="icon-button" aria-label="Tutup detail" @click="transactionDetail=null"><FaIcon :icon="['fas','xmark']" /></button></template></RecordDetailHero><dl class="finance-detail"><div><dt>Jenis</dt><dd>{{ {income:'Pemasukan',expense:'Pengeluaran',transfer:'Transfer'}[transactionDetail.type] }}</dd></div><div><dt>Nominal</dt><dd>{{ formatRupiah(transactionDetail.amount) }}</dd></div><div><dt>Akun</dt><dd>{{ transactionDetail.account?.name||'—' }}<template v-if="transactionDetail.destination_account"> → {{ transactionDetail.destination_account.name }}</template></dd></div><div><dt>Kategori</dt><dd>{{ transactionDetail.category||'—' }}</dd></div><div><dt>Tanggal</dt><dd>{{ dateLabel(transactionDetail.occurred_at) }}</dd></div><div><dt>Catatan</dt><dd>{{ transactionDetail.notes||'Tidak ada catatan' }}</dd></div></dl><p v-if="transactionDetail.savings_goal_id||transactionDetail.payment_records?.length" class="records-hint">Mutasi ini terkait dengan setoran atau pembayaran. Koreksi dari sumber pencatatannya.</p><footer class="finance-detail-actions"><button class="button button--quiet" @click="transactionDetail=null">Tutup</button><button v-if="transactionDetail.type!=='transfer'&&!transactionDetail.savings_goal_id&&!transactionDetail.payment_records?.length" class="button button--quiet" @click="editTransaction(transactionDetail);transactionDetail=null">Ubah</button><button class="button button--quiet danger" @click="voidTransaction(transactionDetail);transactionDetail=null">Batalkan mutasi</button></footer></aside></div>
        </Transition>
        <Transition name="overlay" appear>
        <div v-if="dialog" class="sheet-backdrop" @click.self="dialogGuard.requestClose()"><aside class="guest-sheet finance-sheet" role="dialog" aria-modal="true"><header><div><p class="eyebrow">KEUANGAN BERSAMA</p><h2>{{ {account:selected?'Ubah akun':'Tambah akun',transaction:selected?'Ubah transaksi':'Catat transaksi',category:selected?'Ubah kategori':'Tambah kategori anggaran',obligation:selected?'Ubah kewajiban':'Tambah kewajiban',goal:selected?'Ubah target':'Buat target tabungan',deposit:'Catat setoran',payment:'Catat pembayaran'}[dialog] }}</h2></div><button class="icon-button" aria-label="Tutup form" @click="dialogGuard.requestClose()"><FaIcon :icon="['fas','xmark']" /></button></header>
            <form v-if="dialog==='account'" @submit.prevent="save"><label>Nama akun<input v-model.trim="accountForm.name" required maxlength="120" placeholder="Tunai bersama" /></label><div class="guest-form-row"><label>Jenis<MotionSelect v-model="accountForm.account_type"><option value="cash">Kas tunai</option><option value="bank">Bank</option><option value="other">Lainnya</option></MotionSelect></label><label>Saldo awal<MoneyInput v-model="accountForm.opening_balance" min="0" required /></label></div><label>Bank / institusi<input v-model.trim="accountForm.institution" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan akun' }}</button></form>
            <form v-else-if="dialog==='transaction'" @submit.prevent="save"><label>Jenis transaksi<MotionSelect v-model="transactionForm.type"><option value="expense">Pengeluaran</option><option value="income">Pemasukan</option><option value="transfer">Transfer antar akun</option></MotionSelect></label><label>{{ transactionForm.type==='transfer'?'Dari akun':'Akun' }}<MotionSelect v-model="transactionForm.account_id" required><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{ a.name }}</option></MotionSelect></label><label v-if="transactionForm.type==='transfer'">Ke akun<MotionSelect v-model="transactionForm.destination_account_id" required><option v-for="a in accounts.filter(x=>String(x.id)!==transactionForm.account_id)" :key="a.id" :value="String(a.id)">{{ a.name }}</option></MotionSelect></label><div class="guest-form-row"><label>Jumlah<MoneyInput v-model="transactionForm.amount" min="1" required /></label><label>Tanggal<input v-model="transactionForm.occurred_at" type="date" required /></label></div><label v-if="transactionForm.type!=='transfer'">Kategori<input v-model.trim="transactionForm.category" placeholder="Vendor, konsumsi, lainnya" /></label><label>Deskripsi<input v-model.trim="transactionForm.description" required maxlength="180" /></label><label>Catatan<textarea v-model.trim="transactionForm.notes" rows="2" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan mutasi' }}</button></form>
            <form v-else-if="dialog==='category'" @submit.prevent="save"><label>Nama kategori<input v-model.trim="budgetForm.name" required maxlength="100" placeholder="Venue, konsumsi, dekorasi" /></label><label>Rencana alokasi<MoneyInput v-model="budgetForm.planned_amount" min="0" required /></label><label>Acara<MotionSelect v-model="budgetForm.event_id"><option value="">Semua acara</option><option v-for="e in events" :key="e.id" :value="String(e.id)">{{ e.title }}</option></MotionSelect></label><label>Catatan<textarea v-model.trim="budgetForm.notes" rows="2" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan kategori' }}</button></form>
            <form v-else-if="dialog==='obligation'" @submit.prevent="save"><label>Nama kewajiban<input v-model.trim="obligationForm.title" required maxlength="180" /></label><label>Vendor<input v-model.trim="obligationForm.vendor_name" /></label><div class="guest-form-row"><label>Total kewajiban<MoneyInput v-model="obligationForm.total_amount" min="1" required /></label><label>Jatuh tempo<input v-model="obligationForm.due_at" type="date" /></label></div><label>Kategori anggaran<MotionSelect v-model="obligationForm.budget_category_id"><option value="">Pilih kategori</option><option v-for="c in rows" :key="c.id" :value="String(c.id)">{{ c.name }}</option></MotionSelect></label><label>Acara<MotionSelect v-model="obligationForm.event_id"><option value="">Semua acara</option><option v-for="e in events" :key="e.id" :value="String(e.id)">{{ e.title }}</option></MotionSelect></label><label>Catatan<textarea v-model.trim="obligationForm.notes" rows="2" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan kewajiban' }}</button></form>
            <form v-else-if="dialog==='goal'" @submit.prevent="save"><label>Nama tujuan<input v-model.trim="goalForm.name" required maxlength="140" placeholder="Dana bulan madu" /></label><label>Target nominal<MoneyInput v-model="goalForm.target_amount" min="1" required /></label><label>Tanggal target <em>Opsional</em><input v-model="goalForm.target_date" type="date" /></label><label>Catatan <em>Opsional</em><textarea v-model.trim="goalForm.notes" rows="3" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan target' }}</button></form>
            <form v-else-if="dialog==='deposit'" @submit.prevent="save"><label>Nominal setoran<MoneyInput v-model="depositForm.amount" min="1" required /></label><label>Tanggal setoran<input v-model="depositForm.deposited_at" type="date" required /></label><label>Akun sumber <em>Opsional</em><MotionSelect v-model="depositForm.account_id"><option value="">Tidak memengaruhi saldo akun</option><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{ a.name }}</option></MotionSelect></label><label>Catatan<textarea v-model.trim="depositForm.notes" rows="2" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':selectedDeposit?'Simpan perubahan':'Simpan setoran' }}</button></form>
            <form v-else-if="dialog==='payment'" @submit.prevent="save"><p class="records-hint">Pembayaran akan membuat catatan pengeluaran dan mengurangi saldo akun. Kewajiban tetap menunjukkan sisa termin.</p><label>Akun pembayaran<MotionSelect v-model="paymentForm.account_id" required><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{ a.name }}</option></MotionSelect></label><div class="guest-form-row"><label>Jumlah pembayaran<MoneyInput v-model="paymentForm.amount" min="1" :max="selected.remaining_amount" required /></label><label>Tanggal<input v-model="paymentForm.paid_at" type="date" required /></label></div><label>Catatan<textarea v-model.trim="paymentForm.notes" rows="2" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan pembayaran' }}</button></form>
            <p v-if="formError" class="guest-error" role="alert">{{ formError }}</p>
        </aside></div>
        </Transition>
        <ConfirmDialog :open="confirmOpen" :title="confirmOptions.title" :message="confirmOptions.message" :confirm-label="confirmOptions.confirmLabel" :destructive="confirmOptions.destructive" @cancel="finishConfirm(false)" @confirm="finishConfirm(true)" />
    </section>
